 function nav(v:string){if(!isAdmin&&['users','migration','settings'].includes(v))return;setView(v);setList('Todos');setQuery('');setMobile(false);setDetail(null);}
 const active=entries.filter(r=>!r.deletedAt);
 const byId=(id:string)=>entries.find(r=>r.id===id);
 function label(key:string,module:Module){return definitions[module].fields.find(f=>f.key===key)?.label||({total:'Total',balance:'Saldo pendiente',paymentStatus:'Estado del cobro',updatedAt:'Última actualización'} as any)[key]||key;}
 function value(r:Entry,key:string){const v=key==='name'?r.name:key==='code'?r.code:(r as any)[key]??r.data[key];if(key.endsWith('Id')){const linked=byId(v);return linked?`${linked.module==='invoices'||linked.module==='purchases'?linked.code+' · ':''}${linked.name}`:v||'—';}if(Array.isArray(v))return v.join(', ');if(v===null||v===undefined||v==='')return'—';if(moneyKeys.includes(key))return formatMoney(v);if(typeof v==='boolean')return v?'Sí':'No';return String(v);}
 const invoices=active.filter(r=>r.module==='invoices'&&(!company||r.data.company===company));
 const openInvoices=invoices.filter(r=>!['Cancelar','Devolucion'].includes(r.data.status));
 const totalSales=openInvoices.reduce((n,r)=>n+Number(r.data.total||0),0),receivable=openInvoices.reduce((n,r)=>n+Math.max(0,Number(r.data.balance||0)),0),pending=openInvoices.filter(r=>!r.data.delivered).length;
 const module=modules.includes(view as Module)?view as Module:null;
 const rows=useMemo(()=>{let rr=entries.filter(r=>r.module===view&&(list==='Archivados'?!!r.deletedAt:!r.deletedAt)&&(!company||!r.data.company||r.data.company===company));
 if(query)rr=rr.filter(r=>[r.code,r.name,...Object.values(r.data).filter(x=>typeof x!=='object')].join(' ').toLowerCase().includes(query.toLowerCase()));
 if(list==='Pendientes de entregar')rr=rr.filter(r=>!r.data.delivered&&!['Cancelar','Devolucion'].includes(r.data.status));if(list==='Cuentas por cobrar')rr=rr.filter(r=>Number(r.data.balance)>0);if(list==='Liquidación en contado')rr=rr.filter(r=>r.data.paymentMethod==='Contado');if(list==='Pagadas')rr=rr.filter(r=>Number(r.data.balance)<=0);if(list==='Stock bajo')rr=rr.filter(r=>Number(r.data.stock)<=5);if(list==='Crédito')rr=rr.filter(r=>r.data.paymentMethod==='Credito');if(list==='Duplicados'){const names=rr.map(r=>r.name.trim().toLowerCase());rr=rr.filter(r=>names.filter(n=>n===r.name.trim().toLowerCase()).length>1);}
 return rr.sort((a,b)=>String((a as any)[sort]??a.data[sort]??'').localeCompare(String((b as any)[sort]??b.data[sort]??''),undefined,{numeric:true})*(ascending?1:-1));},[entries,view,query,company,list,sort,ascending]);
 const page=Math.min(pageState,Math.max(1,Math.ceil(rows.length/15)));
 const weeklySales=Array.from({length:7},(_,i)=>{const date=new Date(today()+'T12:00:00-06:00');date.setUTCDate(date.getUTCDate()-6+i);const key=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guatemala',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);return{key,date,sum:openInvoices.filter(r=>r.data.date===key).reduce((n,r)=>n+Number(r.data.total||0),0)};});
 const weeklyMax=Math.max(1,...weeklySales.map(day=>day.sum));
 const filteredReport=useMemo(()=>{const source=report===2?'products':report===7?'invoices':'invoices';let rr=active.filter(r=>r.module===source&&(!company||r.data.company===company)&&(!from||(r.data.date||r.createdAt.slice(0,10))>=from)&&(!until||(r.data.date||r.createdAt.slice(0,10))<=until));if(report===1)rr=rr.filter(r=>!r.data.delivered&&!['Cancelar','Devolucion'].includes(r.data.status));if(report===3)rr=rr.filter(r=>r.data.paymentMethod==='Credito'&&Number(r.data.balance)>0);if(report===4)rr=rr.filter(r=>r.data.delivered&&['Creado','Electronica'].includes(r.data.status));if(report===5){const d=new Date(),start=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-1,1)).toISOString().slice(0,10),end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1)).toISOString().slice(0,10);rr=rr.filter(r=>r.data.dte&&r.data.date>=start&&r.data.date<end);}if(report===7)rr=rr.filter(r=>r.data.advisorId);if(query)rr=rr.filter(r=>`${r.name} ${value(r,'customerId')} ${value(r,'advisorId')} ${r.data.assigned}`.toLowerCase().includes(query.toLowerCase()));return rr;},[entries,report,company,from,until,query]);
 function exportRows(rr:Entry[],kind='csv'){const flat=rr.map(r=>({id:r.id,module:r.module,code:r.code,name:r.name,...Object.fromEntries(Object.entries(r.data).filter(([k])=>k!=='_writeToken')),legacy_id:r.legacyId||'',legacy_module:r.legacyModule||'',created_at:r.createdAt,updated_at:r.updatedAt,version:r.version}));if(kind==='json')download(`gift-${space}-${view}-${today()}.json`,JSON.stringify({format:'gift-backup-v1',exportedAt:new Date().toISOString(),space,records:rr,settings},null,2),'application/json');else download(`gift-${space}-${view}-${today()}.csv`,toCSV(flat));setNotice(`${rr.length} registros exportados`);}
 async function show(r:Entry){const request=++detailRequest.current;setError('');setDetail(r);setDetailTab('Resumen');setDetails({});try{const res=await fetch(endpoint+'&record='+r.id),d=await res.json();if(!res.ok)throw Error(d.error);if(request===detailRequest.current)setDetails(d);}catch(e:any){if(request===detailRequest.current)setError(e.message);}}
 async function save(data:any){if(!editor)return;const r=await act({action:'save',module:editor.module,id:editor.entry?.id,version:editor.entry?.version,data},'Registro guardado');if(r){const parentId=editor.returnTo;setEditor(null);setDetail(null);if(parentId){try{const response=await fetch(endpoint),data=await response.json();if(!response.ok)throw Error(data.error);const parent=data.entries.find((entry:Entry)=>entry.id===parentId);if(parent){await show(parent);setDetailTab('Pagos');}}catch(e:any){setError(e.message);}}}}
 async function loadCSV(file:File){try{if(file.size>1500000)throw Error('Máximo 1,5 MB. Divide la extracción en lotes.');const rows=parseCSV(await file.text());if(rows.length>100)throw Error('Máximo 100 filas por lote en esta versión.');setCsvRows(rows);setMapping(suggestedMapping(importModule,Object.keys(rows[0]||{})));setFilename(file.name);setPreview([]);setError('');}catch(e:any){setError(e.message);}}
